import os, glob, subprocess, openpyxl, docx

def read_docx(p):
    d = docx.Document(p)
    print(f'=== DOCX: {p} ===')
    for para in d.paragraphs:
        if para.text.strip():
            print(para.text)
    for t in d.tables:
        print('--- TABLE ---')
        for r in t.rows:
            print([c.text.strip().replace('\n', ' ') for c in r.cells])

for p in sorted(glob.glob('project/**/*.docx', recursive=True)):
    read_docx(p)

for p in sorted(glob.glob('project/**/*.pdf', recursive=True)):
    print(f'=== PDF: {p} ===')
    out = subprocess.check_output(['pdftotext', '-layout', p, '-']).decode('utf-8', errors='replace')
    print(out)
