import glob, json, ezdxf

for p in sorted(glob.glob('project/**/*.json', recursive=True)):
    with open(p) as f:
        d = json.load(f)
    print(f'=== {p} ===')
    print('params:', d['request']['parameters'])
    data = {k: v for k, v in d['response']['data'].items() if not isinstance(v, (list, dict))}
    print('data:', data)

for p in sorted(glob.glob('project/**/*.dxf', recursive=True)):
    doc = ezdxf.readfile(p)
    print(f'=== DXF: {p} ===')
    msp = doc.modelspace()
    for e in msp:
        if e.dxftype() in ('TEXT', 'MTEXT'):
            txt = e.dxf.text if e.dxftype() == 'TEXT' else e.text
            print(f'  [{e.dxf.layer}] {txt}')
        elif e.dxftype() in ('LINE', 'LWPOLYLINE', 'POLYLINE', 'CIRCLE', 'INSERT'):
            if e.dxftype() == 'LINE':
                print(f'  [{e.dxf.layer}] LINE {tuple(round(x,2) for x in e.dxf.start)} -> {tuple(round(x,2) for x in e.dxf.end)}')
            elif e.dxftype() == 'LWPOLYLINE':
                pts = [(round(p[0],2), round(p[1],2)) for p in e.get_points()]
                print(f'  [{e.dxf.layer}] LWPOLYLINE {pts} closed={e.closed}')
            else:
                print(f'  [{e.dxf.layer}] {e.dxftype()}')
"

