import glob, zlib, re

for p in sorted(glob.glob('project/**/*.pdf', recursive=True)):
    with open(p, 'rb') as f:
        data = f.read()
    streams = re.findall(b'stream\r?\n(.*?)\r?\nendstream', data, re.S)
    print(p, 'streams:', len(streams))
    for i, s in enumerate(streams):
        try:
            dec = zlib.decompress(s).decode('latin1', errors='replace')
            if 'C1' in dec or 'L4x4' in dec or 'SECTION' in dec:
                print(f'  stream {i} len {len(dec)}:')
                for line in dec.splitlines():
                    if 'Tj' in line or 'TJ' in line:
                        print('   ', line)
        except Exception as e:
            pass
"

