            w_conn = {'S': (jc_k, jc_n), 'N': (jc_k, jc_n), 'W': (jc_k, jc_n), 'E': (jc_k, jc_n)}
            r_s08 = run_stage_b(z_assign, c_assign, w_conn, 'Y', +1, 'future', 'final', rigid_mult=1.0, Ax_mult=1.0)
            rr_s12 = run_stage_b(z_assign, c_assign, w_conn, 'Y', -1, 'erection', 'erection', rigid_mult=1e7, Ax_mult=1.0)
            rs_s12_noAx = run_stage_b(z_assign, c_assign, w_conn, 'Y', -1, 'erection', 'erection', rigid_mult=1.0, Ax_mult=1.0)
            rs_s12_Ax = run_stage_b(z_assign, c_assign, w_conn, 'Y', -1, 'erection', 'erection', rigid_mult=1.0, Ax_mult=rr_s12['Ax'])
            if pat in ('P3', 'P4', 'P5') and ch in ('C1', 'C2', 'C3'):
