import sys; sys.path.append('/tmp')
import numpy as np
from check_utilizations import evaluate_design, cases_spec
from stage_b_solver import candidate_lines, deck_patterns

z_assign = {
    'Z1': 'P5', 'Z2': 'P3', 'Z3': 'P3', 'Z4': 'P4',
    'Z5': 'P4', 'Z6': 'P2', 'Z7': 'P2', 'Z8': 'P4',
    'Z9': 'P4', 'Z10': 'P3', 'Z11': 'P3', 'Z12': 'P4',
}
c_assign = {k: 'C1' for k in candidate_lines}
c_assign['CH-S'] = 'C2'; c_assign['CH-N'] = 'C2'
w_conn = {'S': (210.0, 2), 'N': (210.0, 2), 'W': (210.0, 2), 'E': (210.0, 2)}

res = evaluate_design(z_assign, c_assign, w_conn)
for cid, _, _, _, _, _ in cases_spec:
    print(f'{cid}: Cd*d/Ie = {3.2*res[cid][\"disp_load\"]:.3f} in, max_zone = {max(res[cid][\"zone_shears\"].values()):.1f} plf')
for z in [f'Z{i}' for i in range(1, 13)]:
    dem = max(res[cid]['zone_shears'][z] for cid in res)
    cap = 0.60 * deck_patterns[z_assign[z]]['Sn']
    print(f'  {z:3s} ({z_assign[z]}): dem={dem:6.1f} / cap={cap:6.1f} ({dem/cap*100:5.1f}%)')
"

